# parity(dart2wasm/lib/source_map_utils.dart): generated by dev/skeleton.jl from the pinned commit; a filled definition
# replaces its stub in place, and the generator never touches it again.

@parity "dart2wasm/lib/source_map_utils.dart:5 _sourceMapExtensionName" _source_map_extension_name()::String = "x_org_dartlang_dart2js"

"""
Add dart2js source map extension fields to allow mapping "minified:Class123" parts in error
messages to unminified class names like "String".

This is only needed in minified builds. Non-minified builds will have the full class names in the
errors. The extension format is described in `pkg/compiler/doc/sourcemap_extensions.md`.

Its maps are insertion-ordered (`LinkedHashMap`), as dart's map literals are, so the section's JSON
keeps dart's key order. A source map's indices count from 0, as dart's lists do: `names[k]` is Julia's `names[k + 1]`, and
the class id `k` is `class_names[k + 1]`.
"""
@parity "dart2wasm/lib/source_map_utils.dart:15 addMinifiedClassNames" function add_minified_class_names(source_map_json::AbstractDict{String,Any}, class_names::Vector{Union{String,Nothing}})::Nothing
    local names = source_map_json["names"]
    names isa Vector{String} || reject!(Internal("dart2wasm/lib/source_map_utils.dart:19 addMinifiedClassNames: the source map's names are a $(typeof(names))"), "addMinifiedClassNames")

    # Some of the class names may already be in the names list. Create the
    # name->index map with existing names to reuse existing names.
    local name_indices = Dict{String,Int}()
    for i in 0:length(names) - 1
        name_indices[names[i + 1]] = i
    end

    local minified_class_names_to_unminified = LinkedHashMap{String,Int}()
    for class_id in 0:length(class_names) - 1
        local unminified_class_name = class_names[class_id + 1]
        unminified_class_name === nothing && continue
        local minified_class_name = "Class$class_id"
        local unminified_class_name_index = get(name_indices, unminified_class_name, nothing)
        if unminified_class_name_index === nothing
            unminified_class_name_index = length(names)
            push!(names, unminified_class_name)
        end
        minified_class_names_to_unminified[minified_class_name] = unminified_class_name_index
    end

    # 'names' is updated in-place above with the full class names, add the
    # new section.
    #
    # We don't need the "instance" section, but some of the tools want it to be
    # present always.
    local minified_names = LinkedHashMap{String,Any}()
    minified_names["global"] = join(("$k,$v" for (k, v) in minified_class_names_to_unminified), ",")
    minified_names["instance"] = ""
    local extension = LinkedHashMap{String,Any}()
    extension["minified_names"] = minified_names
    source_map_json[_source_map_extension_name()] = extension
    return nothing
end

"""
If the source map has the custom section added by [`add_minified_class_names`], parse the
unminified class names and return the original list* passed to [`add_minified_class_names`].

(*): With the exception that trailing `nothing` elements of the original list will be missing in
the return value of this function.
"""
@parity "dart2wasm/lib/source_map_utils.dart:63 getMinifiedClassNames" function get_minified_class_names(source_map_json::AbstractDict{String,Any})::Union{Vector{Union{String,Nothing}},Nothing}
    local at = "getMinifiedClassNames"
    local names = source_map_json["names"]
    names isa Vector{String} || reject!(Internal("dart2wasm/lib/source_map_utils.dart:64 getMinifiedClassNames: the source map's names are a $(typeof(names))"), at)

    local extension_field = get(source_map_json, _source_map_extension_name(), nothing)
    extension_field === nothing && return nothing

    local global_ = extension_field isa AbstractDict{String,Any} ? get(extension_field, "minified_names", nothing) : nothing
    global_ = global_ isa AbstractDict{String,Any} ? get(global_, "global", nothing) : nothing
    global_ isa String || reject!(Internal("dart2wasm/lib/source_map_utils.dart:69 getMinifiedClassNames: the extension holds no global minified names"), at)
    local global_minified_names = split(global_, ",")

    local unminified_class_names = Union{String,Nothing}[]

    for i in 1:2:length(global_minified_names)
        local minified_class_name = global_minified_names[i]
        startswith(minified_class_name, "Class") && i + 1 <= length(global_minified_names) ||
            reject!(Internal("dart2wasm/lib/source_map_utils.dart:77 getMinifiedClassNames: the minified name '$minified_class_name' is no ClassN,index pair"), at)
        local class_id = tryparse(Int, minified_class_name[ncodeunits("Class") + 1:end])
        local unminified_class_name_index = tryparse(Int, global_minified_names[i + 1])
        class_id !== nothing && unminified_class_name_index !== nothing && 0 <= unminified_class_name_index < length(names) ||
            reject!(Internal("dart2wasm/lib/source_map_utils.dart:78 getMinifiedClassNames: the pair '$minified_class_name,$(global_minified_names[i + 1])' is no class id and name index"), at)
        local unminified_class_name = names[unminified_class_name_index + 1]
        while length(unminified_class_names) <= class_id
            push!(unminified_class_names, nothing)
        end
        unminified_class_names[class_id + 1] === nothing ||
            reject!(Internal("dart2wasm/lib/source_map_utils.dart:85 getMinifiedClassNames: the class id $class_id is named twice"), at)
        unminified_class_names[class_id + 1] = unminified_class_name
    end

    return unminified_class_names
end
